(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.04+t*0.5)*6 + Math.cos(my*0.03-t*0.4)*4;
  const w2y = Math.cos(my*0.035-t*0.45)*6 + Math.sin(mx*0.03+t*0.55)*4;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.65+3)*70,40+Math.cos(t*0.75+1)*50,0.11,2.1],
    [400+Math.cos(t*0.45+2)*60,220+Math.sin(t*0.85+4)*40,0.13,1.8],
    [200+Math.sin(t*0.55+1)*110,200+Math.cos(t*0.65+3)*70,0.05,2.4]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx-sX*0.7+cx*0.3)**2+(sy-sY*0.8+cy*0.2)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d2*f*1.3-t*sp*0.8+0.5); iS2+=Math.cos(d2*f*0.5+t*sp*0.4+2.0);
  }
  const n=src.length;
  const act=aS/n,inh=iS/n,act2=aS2/n,inh2=iS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.1+Math.sin(sx*0.06-sy*0.09+t*1.8)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+(Math.sin(dist*0.08+ang*2-t*2.0)+Math.cos(dist*0.06-ang*5+t*1.8))*0.15;
  const micro=Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.35-t*1.2)*Math.sin((sx-sy)*0.2+t*0.8)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const reaction2=Math.tanh((act2-inh2*0.6+bg*0.2+spiral*0.8+micro)*2.0);
  const cellPhase=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5;
  const cell=Math.tanh(cellPhase*1.5)*0.3;
  const cross=Math.sin(reaction*3.14+reaction2*2.0+t*0.5)*0.15;
  const blend=reaction*0.5+reaction2*0.2+cell*0.15+cross*0.15;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,85],[18,90,115],[20,140,135],[45,170,120],[160,185,65],[210,175,55],[215,130,65],[195,85,60],[155,50,55],[90,25,50],[35,15,45],[6,12,52]];
  const idx=v*(pal.length-2);
  const i=Math.max(0,Math.min(idx|0,pal.length-2));
  const f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.sin(reaction2*Math.PI*0.5)*0.05;
  const edgeStr=Math.abs(reaction)+Math.abs(reaction2)*0.5;
  const edge=edgeStr>0.7?1.0+(edgeStr-0.7)*0.8:1.0;
  const hueShift=reaction2*0.08;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*(1+hueShift)*lum*edge))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*(1-hueShift*0.5)*lum*edge))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*(1+hueShift*0.3)*lum*edge))|0
  ];
}
